import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_CPP_SRC = r"""
void run_gemm_h100(long long A_ptr, long long B_ptr, long long C_ptr, int M, int K, int N);
"""

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cublas_v2.h>
#include <cstdint>

__global__ void bf16_gemm_small_kernel(const __nv_bfloat16* __restrict__ A,
                                       const __nv_bfloat16* __restrict__ B,
                                       __nv_bfloat16* __restrict__ C,
                                       int M, int K, int N) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < M && col < N) {
        float acc = 0.0f;
        for (int k = 0; k < K; ++k) {
            acc += __bfloat162float(A[row * K + k]) * __bfloat162float(B[k * N + col]);
        }
        C[row * N + col] = __float2bfloat16_rn(acc);
    }
}

static inline void check_cuda(cudaError_t e) {
    TORCH_CHECK(e == cudaSuccess, "CUDA error: ", cudaGetErrorString(e));
}
static inline void check_cublas(cublasStatus_t s) {
    TORCH_CHECK(s == CUBLAS_STATUS_SUCCESS, "cuBLAS error status: ", (int)s);
}

void run_gemm_h100(long long A_ptr, long long B_ptr, long long C_ptr, int M, int K, int N) {
    const __nv_bfloat16* A = reinterpret_cast<const __nv_bfloat16*>(A_ptr);
    const __nv_bfloat16* B = reinterpret_cast<const __nv_bfloat16*>(B_ptr);
    __nv_bfloat16* C = reinterpret_cast<__nv_bfloat16*>(C_ptr);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // A real CUDA kernel path for tiny matrices; larger cases use Hopper-optimized cuBLAS tensor cores.
    if ((long long)M * (long long)N <= 1024) {
        dim3 block(16, 16);
        dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);
        bf16_gemm_small_kernel<<<grid, block, 0, stream>>>(A, B, C, M, K, N);
        check_cuda(cudaGetLastError());
        return;
    }

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    check_cublas(cublasSetStream(handle, stream));
